            // start <= pre.tail
            // So we have pre.local_versions[node_id] <= end = post.local_versions[node_id]

            // If min_local_post < min_local_pre, it means that post.local_versions[node_id] = end
            // is now smaller than the previous minimum.
            // But by the reader_state_valid invariant, end <= pre.tail = post.tail
            // So min_local_post <= post.tail

            // The range we're checking is [post.tail, min_local_post + post.buffer_size)
            // Since min_local_post <= post.tail, this range is [post.tail, min_local_post + post.buffer_size)
            // If min_local_post < post.tail, then post.tail >= min_local_post + post.buffer_size would make the range empty
            // But that's not necessarily true.

            // Let's use a different approach. We know that:
            // 1. pre.upcoming_bits_are_not_alive() holds
            // 2. post differs from pre only in local_versions[node_id]

            // By pre invariant: forall |j| pre.tail <= j < min_local_pre + pre.buffer_size ==> !log_entry_is_alive(pre.alive_bits, j, pre.buffer_size)
            // Since post.tail = pre.tail and post.alive_bits = pre.alive_bits and post.buffer_size = pre.buffer_size:
            // forall |j| post.tail <= j < min_local_pre + post.buffer_size ==> !log_entry_is_alive(post.alive_bits, j, post.buffer_size)

            if i < min_local_pre + post.buffer_size {
                // Already covered by the pre invariant
                assert(!log_entry_is_alive(post.alive_bits, i, post.buffer_size));
            } else {
                // i >= min_local_pre + post.buffer_size
                // But we also have i < min_local_post + post.buffer_size and min_local_post < min_local_pre
                // This is impossible because it would require:
                // min_local_pre + post.buffer_size <= i < min_local_post + post.buffer_size
                // Which contradicts min_local_post < min_local_pre
                assert(false);
            }
        }
    };

    // Show that inv_buffer_contents holds for post
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies (
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
        <==> 
        #[trigger] post.contents.contains_key(i)
    ) by {
        // tail, buffer_size, and contents didn't change
        assert(post.tail == pre.tail);
        assert(post.buffer_size == pre.buffer_size);
        assert(post.contents =~= pre.contents);
        assert(post.alive_bits =~= pre.alive_bits);

        // The equivalence follows directly from the pre invariant
        assert(pre.inv_buffer_contents());
    };

    assert forall |i: int| post.tail <= i implies ! #[trigger] post.contents.contains_key(i) by {
        assert(post.contents =~= pre.contents);
        assert(pre.inv_buffer_contents());
    };
}

