#[inductive(reader_finish)]
fn reader_finish_inductive(pre: Self, post: Self, node_id: NodeId) {
    // From the transition
    let end = pre.combiner[node_id].get_Reading_0().get_Range_end();
    let cur = pre.combiner[node_id].get_Reading_0().get_Range_cur();
    assert(cur == end);

    // From reader_state_valid invariant for Range:
    assert(pre.local_versions[node_id] == pre.combiner[node_id].get_Reading_0().get_Range_start());
    assert(pre.combiner[node_id].get_Reading_0().get_Range_start() <= end);
    assert((pre.tail as int) - (pre.buffer_size as int) <= end <= (pre.tail as int));

    // Changes from pre to post:
    assert(post.tail == pre.tail);
    assert(post.buffer_size == pre.buffer_size);
    assert(post.alive_bits =~= pre.alive_bits);
    assert(post.contents =~= pre.contents);
    assert(forall |n| n != node_id && 0 <= n < post.num_replicas ==> post.local_versions[n] == pre.local_versions[n]);
    assert(post.local_versions[node_id] == end);
    assert(post.combiner[node_id] == CombinerState::Idle);
    assert(forall |n| n != node_id && 0 <= n < post.num_replicas ==> post.combiner[n] == pre.combiner[n]);

    // Show that upcoming_bits_are_not_alive holds for post
    let min_local_pre = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat);
    let min_local_post = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);

    // Relationship between min_local_pre and min_local_post:
    // Since post.local_versions only differs from pre.local_versions at index node_id,
    // min_local_post = min(min_local_pre, end) if pre.local_versions[node_id] is involved in the min computation
    // or min_local_post = min_local_pre if pre.local_versions[node_id] > min_local_pre

    // We know from reader_state_valid that end <= pre.tail
    // So we have post.local_versions[node_id] = end <= pre.tail = post.tail

    // Case analysis:
    if end >= min_local_pre {
        // min_local_post = min_local_pre
        assert(min_local_post == min_local_pre);
    } else {
        // min_local_post = end (since end becomes the new minimum)
        assert(min_local_post == end);
    }

    // Use the pre invariant: 
    // forall |i| pre.tail <= i < min_local_pre + pre.buffer_size ==> !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)
    assert(pre.upcoming_bits_are_not_alive());

    // Show post invariant:
    // forall |i| post.tail <= i < min_local_post + post.buffer_size ==> !log_entry_is_alive(post.alive_bits, i, post.buffer_size)
    assert forall |i| post.tail <= i < min_local_post + post.buffer_size implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        assert(post.tail == pre.tail);
        assert(post.alive_bits =~= pre.alive_bits);
        assert(post.buffer_size == pre.buffer_size);

        if min_local_post == min_local_pre {
            // The range is the same, so the result follows from pre invariant
            assert(i < min_local_pre + pre.buffer_size);
            assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
            assert(!log_entry_is_alive(post.alive_bits, i, post.buffer_size));
        } else {
            // min_local_post = end < min_local_pre
            assert(min_local_post == end);
            // We need to show: forall |i| post.tail <= i < end + post.buffer_size ==> !log_entry_is_alive(post.alive_bits, i, post.buffer_size)

            // We know end <= post.tail, so we're looking at the range [post.tail, end + post.buffer_size)
            // For i in [post.tail, min_local_pre + pre.buffer_size): already covered by pre invariant
            // For i in [min_local_pre + pre.buffer_size, end + post.buffer_size): need to show not alive
            // But since end < min_local_pre, we have end + post.buffer_size < min_local_pre + post.buffer_size
            // So the second range is actually empty or...

            // Actually, let's be more precise. Since end <= post.tail and end < min_local_pre:
            // If post.tail <= min_local_pre, then [post.tail, end + post.buffer_size) is contained in [post.tail, min_local_pre + post.buffer_size)
            // If post.tail > min_local_pre, then we need to be more careful...

            // But we know from reader_state_valid that end <= post.tail, so the range [post.tail, end + post.buffer_size) 
            // is well-defined and non-empty only if end + post.buffer_size > post.tail, i.e., if end > post.tail - post.buffer_size

            // In any case, since post.alive_bits == pre.alive_bits, and we're just changing local_versions (which doesn't affect alive_bits),
            // and the pre invariant holds, we can derive the result.
        }
    };

    // Show that inv_buffer_contents holds for post
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies (
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
        <==> 
        #[trigger] post.contents.contains_key(i)
    ) by {
        assert(post.tail == pre.tail);
        assert(post.buffer_size == pre.buffer_size);
