        // the equivalence follows from the pre invariant and the relationship between 
        // map_min_value(pre.local_versions, ...) and map_min_value(post.local_versions, ...)

        assert(pre.inv_buffer_contents());
    };

    assert forall |i: int| post.tail <= i implies ! #[trigger] post.contents.contains_key(i) by {
        assert(post.contents =~= pre.contents);
        assert(pre.inv_buffer_contents());
    };
