#[inductive(reader_finish)]
fn reader_finish_inductive(pre: Self, post: Self, node_id: NodeId) {
    // Extract values from the transition
    let end = pre.combiner[node_id].get_Reading_0().get_Range_end();
    let cur = pre.combiner[node_id].get_Reading_0().get_Range_cur();
    assert(cur == end);

    // From reader_state_valid invariant for Range:
    assert((pre.tail as int) - (pre.buffer_size as int) <= end <= (pre.tail as int));

    // Changes from pre to post:
    assert(post.tail == pre.tail);
    assert(post.buffer_size == pre.buffer_size);
    assert(post.alive_bits =~= pre.alive_bits);
    assert(post.contents =~= pre.contents);
    assert(forall |n| n != node_id && 0 <= n < post.num_replicas ==> post.local_versions[n] == pre.local_versions[n]);
    assert(post.local_versions[node_id] == end);

    // Show that upcoming_bits_are_not_alive holds for post
    // Pre invariant: forall |i| pre.tail <= i < map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat) + pre.buffer_size ==> !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)
    assert(pre.upcoming_bits_are_not_alive());

    // Post invariant to show: forall |i| post.tail <= i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat) + post.buffer_size ==> !log_entry_is_alive(post.alive_bits, i, post.buffer_size)

    assert forall |i| post.tail <= i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat) + post.buffer_size implies !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {
        assert(post.tail == pre.tail);
        assert(post.alive_bits =~= pre.alive_bits);
        assert(post.buffer_size == pre.buffer_size);

        // Key insight: since post.local_versions only differs from pre.local_versions at index node_id,
        // and post.local_versions[node_id] = end where end <= pre.tail = post.tail,
        // the set of indices where the invariant needs to be checked can only shrink or stay the same.

        // More precisely, let min_pre = map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat)
        // and min_post = map_min_value(post.local_versions, (post.num_replicas - 1) as nat)

        // Since post.local_versions[n] = pre.local_versions[n] for n ≠ node_id and post.local_versions[node_id] = end,
        // we have min_post ≥ min(min_pre, end)

        // By pre invariant, we know that for all i such that pre.tail ≤ i < min_pre + pre.buffer_size,
        // we have !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)

        // Since post.tail = pre.tail, post.alive_bits = pre.alive_bits, post.buffer_size = pre.buffer_size,
        // it suffices to show that the range [post.tail, min_post + post.buffer_size) is contained in
        // [pre.tail, min_pre + pre.buffer_size)

        // This follows from the fact that min_post cannot be much smaller than min_pre, 
        // and end is bounded by pre.tail.
    };

    // Show that inv_buffer_contents holds for post
    assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies (
        (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
        <==> 
        #[trigger] post.contents.contains_key(i)
    ) by {
        assert(post.tail == pre.tail);
        assert(post.buffer_size == pre.buffer_size);
        assert(post.contents =~= pre.contents);
        assert(post.alive_bits =~= pre.alive_bits);

        // The biconditional holds because:
        // 1. The content, tail, and buffer_size are unchanged
        // 2. The only change is in local_versions, which affects the second disjunct of the left side
        // 3. The pre invariant ensures the biconditional held before the transition
        // 4. The relationship between map_min_value(pre.local_versions, ...) and map_min_value(post.local_versions, ...)
        //    ensures that the modified disjunct doesn't break the equivalence
        assert(pre.inv_buffer_contents());
    };

    assert forall |i: int| post.tail <= i implies ! #[trigger] post.contents.contains_key(i) by {
        assert(post.contents =~= pre.contents);
        assert(pre.inv_buffer_contents());
    };
}

